import csv, re

# For component-specific categories (OPEN, SHORT, COLD_SOLDER), 
# the net mentioned in the text (or test_item) needs to map to net in codebook
# Build the net -> codebook entries mapping for each product

for fname, pid in [('codebook_P1_POWER.csv', 'P1_POWER'), 
                    ('codebook_P2_CTRL.csv', 'P2_CTRL'),
                    ('codebook_P3_RF.csv', 'P3_RF')]:
    print(f'=== {pid} Net Mapping ===')
    net_map = {}  # net -> {cat2 -> [entries]}
    with open(f'/app/data/{fname}', 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        seen = set()
        for row in reader:
            label = row['standard_label']
            if label in seen:
                continue
            seen.add(label)
            cat2 = row['category_lv2']
            if cat2 in ('OPEN', 'SHORT'):
                m = re.search(r':\s*(\w+)\s*/\s*(\w+)', label)
                if m:
                    net = m.group(2)
                    if net not in net_map:
                        net_map[net] = {}
                    if cat2 not in net_map[net]:
                        net_map[net][cat2] = []
                    net_map[net][cat2].append(row['code'])
    for net, cats in sorted(net_map.items()):
        for cat2, codes in sorted(cats.items()):
            print(f'  {net:15s} {cat2:8s} -> {codes}')
    print()
" 2>&1

